//! F06 real loopback HTTP + real isolated PostgreSQL + documented offline CLI.
//! All accounts/mail/sessions are disposable synthetic fixtures; no production input.
use serde_json::{Value,json};
use std::{collections::BTreeMap,sync::{Arc,atomic::{AtomicUsize,Ordering}},time::Duration};
use tokio::io::{AsyncBufReadExt,AsyncWriteExt,BufReader};
use weebdex_platform::{AppState,Config,domains};
use sha2::{Digest,Sha256};
struct Server(tokio::task::JoinHandle<()>);impl Drop for Server{fn drop(&mut self){self.0.abort();}}
#[derive(Clone,Default)]struct Browser{cookies:BTreeMap<String,String>,account:String}
impl Browser{
 async fn call(&mut self,http:&reqwest::Client,origin:&str,method:&str,path:&str,body:Option<Value>,expected:u16)->Value{
  let mut r=http.request(method.parse().unwrap(),format!("{origin}{path}")).header("origin",origin).header("content-type","application/json");
  if !self.account.is_empty(){r=r.header("x-weebdex-expected-account",&self.account);}if !self.cookies.is_empty(){r=r.header("cookie",self.cookies.iter().map(|(k,v)|format!("{k}={v}")).collect::<Vec<_>>().join("; "));}if let Some(body)=body{r=r.json(&body);}
  let response=r.send().await.unwrap();let status=response.status().as_u16();for h in response.headers().get_all("set-cookie"){let pair=h.to_str().unwrap().split(';').next().unwrap();let(k,v)=pair.split_once('=').unwrap();self.cookies.insert(k.into(),v.into());}
  let text=response.text().await.unwrap();let v:Value=serde_json::from_str(&text).unwrap_or(Value::Null);assert_eq!(status,expected,"{method} {path}: {v}");v
 }
}
fn csrf(v:&Value)->String{v["ui"]["nodes"].as_array().unwrap().iter().find(|n|n["attributes"]["name"]=="csrf_token").unwrap()["attributes"]["value"].as_str().unwrap().into()}
const PASSWORD:&str="Disposable-staff-password-7";
async fn register(http:&reqwest::Client,origin:&str,name:&str)->Browser{let mut b=Browser::default();let f=b.call(http,origin,"GET","/auth/self-service/registration/browser",None,200).await;let v=b.call(http,origin,"POST",&format!("/auth/self-service/registration?flow={}",f["id"].as_str().unwrap()),Some(json!({"method":"password","csrf_token":csrf(&f),"traits":{"username":name,"email":format!("{name}@example.invalid")},"password":PASSWORD})),200).await;b.account=v["session"]["identity"]["id"].as_str().unwrap().into();b}
async fn login(http:&reqwest::Client,origin:&str,b:&mut Browser,name:&str){let f=b.call(http,origin,"GET","/auth/self-service/login/browser?refresh=true&return_to=%2Fstaff%2Fusers",None,200).await;b.call(http,origin,"POST",&format!("/auth/self-service/login?flow={}",f["id"].as_str().unwrap()),Some(json!({"method":"password","csrf_token":csrf(&f),"identifier":name,"password":PASSWORD})),200).await;}
async fn mail_link(http:&reqwest::Client,origin:&str,sink:&Arc<tokio::sync::Mutex<Vec<Value>>>,kind:&str,name:&str)->(Browser,String){let mut b=Browser::default();let f=b.call(http,origin,"GET",&format!("/auth/self-service/{kind}/browser"),None,200).await;b.call(http,origin,"POST",&format!("/auth/self-service/{kind}?flow={}",f["id"].as_str().unwrap()),Some(json!({"method":"link","csrf_token":csrf(&f),"email":format!("{name}@example.invalid")})),200).await;let messages=sink.lock().await;let text=messages.last().unwrap()["text"].as_str().unwrap();let url=url::Url::parse(text.lines().find(|v|v.starts_with(origin)).unwrap()).unwrap();(b,format!("{}?{}",url.path(),url.query().unwrap()))}
async fn verify(http:&reqwest::Client,origin:&str,sink:&Arc<tokio::sync::Mutex<Vec<Value>>>,name:&str){let(mut b,path)=mail_link(http,origin,sink,"verification",name).await;b.call(http,origin,"GET",&path,None,303).await;}
fn command(target:&Value,operation:&str,bundles:&[&str])->Value{static N:AtomicUsize=AtomicUsize::new(1);json!({"requestId":format!("10800000-0000-4000-8000-{:012}",N.fetch_add(1,Ordering::SeqCst)),"targetId":target["id"],"authorityVersion":target["authorityVersion"],"operation":operation,"bundles":bundles,"reason":"Disposable acceptance review","replaceCustom":operation=="roles"&&target["customAuthority"]==true,"ownerRequested":operation=="reactivate"})}
async fn target(b:&mut Browser,h:&reqwest::Client,o:&str,id:&str)->Value{b.call(h,o,"GET",&format!("/api/staff/admin/users/{id}"),None,200).await["target"].clone()}
async fn review(b:&mut Browser,h:&reqwest::Client,o:&str,c:&Value,status:u16)->Value{b.call(h,o,"POST",&format!("/api/staff/admin/users/{}/review",c["targetId"].as_str().unwrap()),Some(c.clone()),status).await}
async fn apply(b:&mut Browser,h:&reqwest::Client,o:&str,c:&Value,status:u16)->Value{b.call(h,o,"POST",&format!("/api/staff/admin/users/{}/commands",c["targetId"].as_str().unwrap()),Some(c.clone()),status).await}
async fn change(b:&mut Browser,h:&reqwest::Client,o:&str,id:&str,op:&str,bundles:&[&str])->Value{let t=target(b,h,o,id).await;let c=command(&t,op,bundles);review(b,h,o,&c,200).await;apply(b,h,o,&c,200).await}
async fn seed_private_link(state:&AppState,user:&str,key:&str,challenge:&str){let db=state.db.client().await.unwrap();let session:String=db.query_one("SELECT id FROM platform.sessions WHERE user_id=$1 AND purpose='normal' AND revoked_at IS NULL ORDER BY created_at DESC LIMIT 1",&[&user]).await.unwrap().get(0);db.execute("INSERT INTO platform.native_identity_links(user_id,public_key,revision) VALUES($1,$2,1)",&[&user,&key]).await.unwrap();db.execute("INSERT INTO platform.native_identity_link_challenges(id,user_id,session_id,action,public_key,revision,payload,expires_at) VALUES($1,$2,$3,'unlink',$4,1,'disposable lifecycle fixture only',clock_timestamp()+interval '10 minutes')",&[&challenge,&user,&session,&key]).await.unwrap();}
async fn close_account(b:&mut Browser,h:&reqwest::Client,o:&str,status:u16)->Value{let id=b.account.clone();let snap=b.call(h,o,"GET",&format!("/api/account/closure/{id}"),None,200).await;let capture=json!({"expectedAccountId":id,"expectedUserId":id,"expectedLifecycleId":snap["lifecycleId"],"version":snap["version"]});let prepared=b.call(h,o,"POST","/api/account/closure/prepare",Some(capture.clone()),200).await;assert_eq!(prepared["result"],"prepared");b.call(h,o,"POST","/api/account/closure/confirm",Some(json!({"capture":capture,"confirmationId":prepared["confirmationId"],"confirmationToken":prepared["confirmationToken"],"acknowledge":"DISABLE THIS ACCOUNT"})),status).await}
async fn bootstrap_cli(dsn:&str,config:&std::path::Path,id:&str,confirm:bool)->(bool,String){let mut process=tokio::process::Command::new(env!("CARGO_BIN_EXE_weebdex-admin")).args(["bootstrap","--user",id,"--reason","Disposable clean deployment bootstrap"])
 .env("PLATFORM_DATABASE_URL",dsn).env("PLATFORM_CONFIG",config).stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).kill_on_drop(true).spawn().unwrap();
 let mut stdout=BufReader::new(process.stdout.take().unwrap()).lines();let mut printed=String::new();while let Some(line)=stdout.next_line().await.unwrap(){printed.push_str(&line);printed.push('\n');if line.starts_with("BOOTSTRAP "){process.stdin.as_mut().unwrap().write_all(if confirm{format!("{line}\n")}else{"cancel\n".into()}.as_bytes()).await.unwrap();}}
 let status=process.wait().await.unwrap();(status.success(),printed)
}
