 let t=target(&mut a,&h,&origin,&ids[4]).await;let revoke=command(&t,"revoke-sessions",&[]);review(&mut a,&h,&origin,&revoke,200).await;let mut holder=state.db.client().await.unwrap();let held=holder.transaction().await.unwrap();held.query_one("SELECT id FROM platform.sessions WHERE id='staff-recovery' FOR UPDATE",&[]).await.unwrap();let before_audit:i64=state.db.client().await.unwrap().query_one("SELECT count(*) FROM platform.security_audit",&[]).await.unwrap().get(0);let start=std::time::Instant::now();apply(&mut a,&h,&origin,&revoke,409).await;assert!(start.elapsed()<Duration::from_secs(2));assert_eq!(target(&mut a,&h,&origin,&ids[4]).await["authorityVersion"],t["authorityVersion"]);assert_eq!(state.db.client().await.unwrap().query_one("SELECT count(*) FROM platform.security_audit",&[]).await.unwrap().get::<_,i64>(0),before_audit);held.rollback().await.unwrap();drop(holder);let revoked=apply(&mut a,&h,&origin,&revoke,200).await;assert_eq!(revoked["effects"]["recoverySessions"],1);assert_eq!(revoked["effects"]["apiCredentials"],1);let receipt=a.call(&h,&origin,"GET",&format!("/api/staff/admin/receipts/{}",revoke["requestId"].as_str().unwrap()),None,200).await;assert_eq!(receipt,revoked);assert_eq!(apply(&mut a,&h,&origin,&revoke,200).await,revoked);people[4].call(&h,&origin,"GET","/api/staff/admin/context",None,401).await;b.call(&h,&origin,"GET","/api/staff/admin/context",None,200).await;
 // Self-session revocation signs out the browser but preserves password and
 // administrator eligibility. Its own durable receipt is available after login.
 let own=target(&mut a,&h,&origin,&ids[0]).await;let signout=command(&own,"revoke-sessions",&[]);review(&mut a,&h,&origin,&signout,200).await;let signed_out=apply(&mut a,&h,&origin,&signout,200).await;assert!(signed_out["effects"]["ordinarySessions"].as_u64().unwrap()>0);a.call(&h,&origin,"GET",&format!("/api/staff/admin/receipts/{}",signout["requestId"].as_str().unwrap()),None,401).await;a=Browser{account:ids[0].clone(),..Default::default()};login(&h,&origin,&mut a,"staff-fixture-0").await;assert_eq!(a.call(&h,&origin,"GET",&format!("/api/staff/admin/receipts/{}",signout["requestId"].as_str().unwrap()),None,200).await,signed_out);
 // Last-admin race: two administrators independently review their own demotion.
 // Exactly one succeeds; the other fails current actor review or last-admin guard.
 let ta=target(&mut a,&h,&origin,&ids[0]).await;let tb=target(&mut b,&h,&origin,&ids[1]).await;let ca=command(&ta,"roles",&[]);let cb=command(&tb,"roles",&[]);review(&mut a,&h,&origin,&ca,200).await;review(&mut b,&h,&origin,&cb,200).await;
 let request=|browser:&Browser,c:&Value|h.post(format!("{origin}/api/staff/admin/users/{}/commands",c["targetId"].as_str().unwrap())).header("origin",&origin).header("x-weebdex-expected-account",&browser.account).header("cookie",browser.cookies.iter().map(|(k,v)|format!("{k}={v}")).collect::<Vec<_>>().join("; ")).json(c).send();let(ra,rb)=tokio::join!(request(&a,&ca),request(&b,&cb));let(sa,sb)=(ra.unwrap().status().as_u16(),rb.unwrap().status().as_u16());assert!(matches!((sa,sb),(200,409)|(409,200)),"last-admin race statuses {sa}/{sb}");let mut remaining=if sa==200{b.clone()}else{a.clone()};let db=state.db.client().await.unwrap();assert_eq!(db.query_one("SELECT count(*) FROM platform.users WHERE platform.eligible_roles_administrator(verified,disabled,roles,permissions)",&[]).await.unwrap().get::<_,i64>(0),1);let sole=remaining.account.clone();for sql in ["UPDATE platform.users SET disabled=true WHERE id=$1","UPDATE platform.users SET verified=false WHERE id=$1","UPDATE platform.users SET roles='[\"restricted\"]' WHERE id=$1","UPDATE platform.users SET permissions='[]' WHERE id=$1","DELETE FROM platform.users WHERE id=$1"]{assert_eq!(db.execute(sql,&[&sole]).await.unwrap_err().code().unwrap().code(),"P6001");}assert_eq!(db.execute("UPDATE platform.security_audit SET reason='tamper'",&[]).await.unwrap_err().code().unwrap().code(),"42501");assert_eq!(db.execute("DELETE FROM platform.security_receipts",&[]).await.unwrap_err().code().unwrap().code(),"42501");drop(db);
 // Read surfaces are explicitly selected and contain no credentials/profile/email.
 let list=remaining.call(&h,&origin,"GET","/api/staff/admin/users",None,200).await;let history=remaining.call(&h,&origin,"GET","/api/staff/admin/audit",None,200).await;let text=format!("{list}{history}");for forbidden in ["password_hash","token_hash","secret_hash","@example.invalid",PASSWORD,"disposable-recovery","disposable-api"]{assert!(!text.contains(forbidden),"redaction failure: {forbidden}");}assert!(history["data"].as_array().unwrap().iter().any(|r|r["operation"]=="bootstrap"));
 println!("F06: 8 real registered principals; verified offline CLI cancel/bootstrap/refusal; independent minimal grants; freshness/normal reauth; sole-admin email rollback and password recovery; role/restriction/reactivation/revoke CAS; exact receipts; concurrent final-admin protection; redacted append-only history passed");
